@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* The real label, for screen readers and find-in-page. */
.label {
  composes: srOnly from "../text/text.module.css";
}

/* Block padding keeps descenders inside the mask. */
@property --morph-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  .root {
    position: relative;
    display: inline-flex;
    white-space: pre;
  }

  .row {
    --morph-to: right;
    position: relative;
    display: inline-flex;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  :is([dir="rtl"]) .row {
    --morph-to: left;
  }

  .row[data-morphing] {
    mask-image: linear-gradient(to var(--morph-to), #000 calc(100% - var(--morph-fade)), transparent);
  }

  /* A filter (the blur on arriving and leaving letters) paints only inside
     the element's box, and a glyph's descender hangs below a tight line box.
     The block padding grows each letter's box to hold its descenders; the
     negative margin gives the room back, so nothing moves. */
  .glyph {
    display: inline-block;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  .ghosts {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Sits where the letter sat: the row's block padding, held as the ghost's
     own padding so its blur has room for descenders too. */
  .ghost {
    position: absolute;
    top: 0;
    padding-block: 0.3em;
  }
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import styles from "./text-morph.module.css";

type Glyph = { key: string; char: string };
type Layout = { text: string; glyphs: Glyph[]; lefts: Map<string, number>; width: number };

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function split(text: string) {
  return segmenter ? Array.from(segmenter.segment(text), (s) => s.segment) : Array.from(text);
}

type Word = { start: number; end: number; text: string };

function words(chars: string[]): Word[] {
  const out: Word[] = [];
  let start = -1;
  chars.forEach((c, i) => {
    const space = /\s/.test(c);
    if (!space && start === -1) start = i;
    if (space && start !== -1) {
      out.push({ start, end: i, text: chars.slice(start, i).join("").toLowerCase() });
      start = -1;
    }
  });
  if (start !== -1) out.push({ start, end: chars.length, text: chars.slice(start).join("").toLowerCase() });
  return out;
}

/** Shared start and end letters: "Copy" → "Copied" keeps "Cop". */
function edges(a: string[], b: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) pairs.push([start, start++]);
  for (let k = 1; k <= Math.min(a.length, b.length) - start && a[a.length - k] === b[b.length - k]; k++) {
    pairs.push([a.length - k, b.length - k]);
  }
  return pairs;
}

/** Keys letters, reusing old keys for shared words and gap edges so they slide. */
function toGlyphs(prev: Glyph[] | null, text: string, generation: number): Glyph[] {
  // Same keys on the server and in the browser.
  const fresh = (i: number) => `${generation}:${i}`;
  const chars = split(text);
  if (!prev) return chars.map((char, i) => ({ key: fresh(i), char }));
  const keys: (string | null)[] = chars.map(() => null);
  const old = prev.map((g) => g.char);

  // Numbers match by place value, from the right.
  if (numeric(old.join("")) && numeric(text)) {
    for (let k = 1; k <= Math.min(old.length, chars.length); k++) {
      if (old[old.length - k] === chars[chars.length - k]) keys[chars.length - k] = prev[old.length - k].key;
    }
    return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
  }

  const oldWords = words(old);
  const used = new Set<number>();
  const anchors: { from: Word; to: Word }[] = [];
  for (const w of words(chars)) {
    const i = oldWords.findIndex((o, k) => !used.has(k) && o.text === w.text);
    if (i === -1) continue;
    used.add(i);
    anchors.push({ from: oldWords[i], to: w });
    for (let k = 0; k < w.end - w.start; k++) {
      if (old[oldWords[i].start + k] === chars[w.start + k]) keys[w.start + k] = prev[oldWords[i].start + k].key;
    }
  }

  const ordered = anchors.every((a, i) => i === 0 || a.from.start > anchors[i - 1].from.end);
  if (ordered) {
    const bounds = [{ from: 0, to: 0 }, ...anchors.map((a) => ({ from: a.from.end, to: a.to.end }))];
    const ends = [...anchors.map((a) => ({ from: a.from.start, to: a.to.start })), { from: old.length, to: chars.length }];
    bounds.forEach((b, g) => {
      const pairs = edges(old.slice(b.from, ends[g].from), chars.slice(b.to, ends[g].to));
      for (const [i, j] of pairs) keys[b.to + j] = prev[b.from + i].key;
    });
  }

  return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
}

const NUMERIC = /^[^\p{L}]*\d[^\p{L}]*$/u;
const numeric = (text: string) => NUMERIC.test(text);

const NUMBER = /[-\u2212]?\d[\d,.]*/;

function value(text: string) {
  const match = text.match(NUMBER);
  return match ? parseFloat(match[0].replace("\u2212", "-").replace(/,/g, "")) : NaN;
}

function direction(from: string, to: string) {
  const delta = value(to) - value(from);
  return Number.isNaN(delta) ? 0 : Math.sign(delta);
}

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

function translateX(el: Element) {
  const transform = getComputedStyle(el).transform;
  return transform && transform !== "none" ? new DOMMatrixReadOnly(transform).m41 : 0;
}

function measureText(row: HTMLElement, text: string, glyphs: Glyph[]): Layout {
  const node = row.firstChild;
  const origin = row.getBoundingClientRect().left;
  const lefts = new Map<string, number>();
  let width = 0;
  if (node?.nodeType === Node.TEXT_NODE) {
    const range = document.createRange();
    let offset = 0;
    for (const g of glyphs) {
      range.setStart(node, offset);
      range.setEnd(node, (offset += g.char.length));
      const box = range.getBoundingClientRect();
      lefts.set(g.key, box.left - origin);
      width = Math.max(width, box.right - origin);
    }
  }
  return { text, glyphs, lefts, width };
}

export function TextMorph({ children, className }: { children: string; className?: string }) {
  const [shown, setShown] = useState(children);
  const [state, setState] = useState(() => ({ generation: 0, glyphs: toGlyphs(null, children, 0) }));
  if (shown !== children) {
    setShown(children);
    setState((prev) => ({ generation: prev.generation + 1, glyphs: toGlyphs(prev.glyphs, children, prev.generation + 1) }));
  }
  const { glyphs } = state;
  // Plain text until the label first changes.
  const split = state.generation > 0;
  const rowRef = useRef<HTMLSpanElement>(null);
  const ghostsRef = useRef<HTMLSpanElement>(null);
  const layout = useRef<Layout | null>(null);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const ghosts = ghostsRef.current;
    if (!row || !ghosts) return;

    if (!split) {
      layout.current = measureText(row, children, glyphs);
      return;
    }

    const nodes = new Map<string, HTMLElement>();
    for (const el of row.querySelectorAll<HTMLElement>("[data-glyph]")) nodes.set(el.dataset.glyph!, el);

    const last = layout.current;
    const lefts = new Map(glyphs.map((g) => [g.key, nodes.get(g.key)!.offsetLeft]));
    const tail = nodes.get(glyphs.at(-1)?.key ?? "");
    // Fractional, like the row's own width: offsetWidth rounds, and the
    // animation would end half a pixel short and then snap.
    const width = tail ? tail.getBoundingClientRect().right - row.getBoundingClientRect().left : 0;
    layout.current = { text: children, glyphs, lefts, width };

    if (!last || last.text === children) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ghosts.replaceChildren();
      return;
    }

    // The glide, not the move spring: a spring's overshoot narrows a button
    // past its new width and springs it back, which reads as the control
    // settling after the click. The glide lands once.
    const spring = token(row, "--ui-ease-glide", "cubic-bezier(0.22, 1, 0.36, 1)");
    const easeExit = token(row, "--ui-ease-exit", "cubic-bezier(0.4, 0, 1, 1)");
    const duration = ms(token(row, "--ui-dur-glide", "320ms"));
    const exit = ms(token(row, "--ui-dur-instant", "150ms"));
    // Letters arrive on the plain enter curve: a spring would bounce them
    // up and down, and vertical bounce reads as jitter in a line of text.
    const enter = token(row, "--ui-ease-enter", "cubic-bezier(0.2, 1, 0.3, 1)");

    // If a previous morph is still running, start from where it visibly is.
    const running = row.getAnimations();
    const fromWidth = running.length ? row.getBoundingClientRect().width : last.width;
    running.forEach((a) => a.cancel());
    const fade = Math.min(16, Math.abs(width - fromWidth));
    row.dataset.morphing = "";
    const grow = row.animate(
      { width: [`${fromWidth}px`, `${width}px`], ["--morph-fade" as string]: [`${fade}px`, "0px"] },
      { duration, easing: spring },
    );
    grow.finished.then(
      () => delete row.dataset.morphing,
      () => {}, // cancelled by a newer morph, which owns the flag now
    );

    const dir = direction(last.text, children) || 1;
    // A small rise with a soft blur: the change reads, the line holds still.
    const enterFrom = `translateY(${0.08 * dir}em)`;
    const leaveTo = `translateY(${-0.08 * dir}em)`;

    // Arrivals wait for leaving letters to clear.
    const current = new Set(glyphs.map((g) => g.key));
    const leaving = last.glyphs.some((g) => !current.has(g.key));
    const lead = exit * (leaving ? 0.85 : 0.4);
    let entering = 0;
    for (const g of glyphs) {
      const el = nodes.get(g.key)!;
      const before = last.lefts.get(g.key);
      if (before === undefined) {
        el.animate(
          {
            opacity: [0, 1],
            transform: [enterFrom, "none"],
            filter: ["blur(2px)", "none"],
          },
          { duration: duration * 0.75, easing: enter, delay: lead + entering++ * 15, fill: "backwards" },
        );
        continue;
      }
      // FLIP from where the letter is on screen now.
      const offset = before + translateX(el) - lefts.get(g.key)!;
      el.getAnimations().forEach((a) => a.cancel());
      if (Math.abs(offset) > 0.5) {
        el.animate({ transform: [`translateX(${offset}px)`, "none"] }, { duration, easing: spring });
      }
    }

    // Ghosts live in a layer React never renders into.
    const kept = new Set(glyphs.map((g) => g.key));
    for (const g of last.glyphs) {
      if (kept.has(g.key)) continue;
      const ghost = document.createElement("span");
      ghost.className = styles.ghost;
      ghost.textContent = g.char;
      ghost.style.left = `${last.lefts.get(g.key)}px`;
      ghosts.append(ghost);
      const fade = ghost.animate(
        {
          opacity: [1, 0],
          transform: ["none", leaveTo],
          filter: ["none", "blur(2px)"],
        },
        { duration: exit, easing: easeExit, fill: "forwards" },
      );
      fade.finished.then(
        () => ghost.remove(),
        () => ghost.remove(),
      );
    }
  }, [children, glyphs, split]);

  return (
    // The letter row must run in the label's own direction.
    <span className={className ? `${styles.root} ${className}` : styles.root} dir="auto">
      <span className={styles.label}>{children}</span>
      <span ref={rowRef} className={styles.row} aria-hidden="true">
        {split
          ? glyphs.map((g) => (
              <span key={g.key} data-glyph={g.key} className={styles.glyph}>
                {g.char}
              </span>
            ))
          : children}
        <span ref={ghostsRef} className={styles.ghosts} />
      </span>
    </span>
  );
}

import type { ComponentProps, ElementType } from "react";
import styles from "./button.module.css";

// No "use client", so it renders on the server and `as` can take a server-side link.
type ButtonLinkProps = ComponentProps<"a"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Your router's link component, so navigation stays client-side. Defaults to a plain <a>. */
  as?: ElementType;
};

/** A link that looks like a button, for navigation. Same variants and sizes. */
export function ButtonLink({ variant = "primary", size = "md", as: Link = "a", className, children, ...props }: ButtonLinkProps) {
  return (
    <Link
      data-variant={variant}
      data-size={size}
      className={className ? `${styles.button} ${className}` : styles.button}
      {...props}
    >
      <span className={styles.content}>{children}</span>
    </Link>
  );
}

@layer theme, base, components, utilities;

@property --button-dim {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@layer components {
  .button {
    --button-bg: transparent;
    --button-bg-hover: var(--ui-fill);
    --button-bg-press: var(--ui-fill-strong);
    --button-fg: var(--ui-foreground);
    --button-edge: transparent;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    position: relative;
    display: inline-grid;
    place-items: center;
    flex-shrink: 0;
    height: var(--ui-control-md);
    min-width: var(--ui-control-md);
    padding-inline: 20px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: none;
    color: var(--button-fg);
    isolation: isolate;
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    letter-spacing: var(--ui-tracking-control);
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Fill and edge on their own layer, so a press scales the shape, not the label. */
  .button::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--button-bg);
    box-shadow:
      inset 0 0 0 var(--ui-hairline) var(--button-edge),
      var(--button-depth, 0 0 transparent);
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* Icon only (one element, named by aria-label): a capsule, not a circle,
     like every other button. */
  .button[data-icon-only] {
    width: calc(var(--ui-control-md) * var(--ui-capsule));
    padding-inline: 0;
  }

  .button[data-size="sm"][data-icon-only] {
    width: calc(var(--ui-control-sm) * var(--ui-capsule));
  }

  .button[data-size="lg"][data-icon-only] {
    width: calc(var(--ui-control-lg) * var(--ui-capsule));
  }

  .button[data-size="sm"] {
    height: var(--ui-control-sm);
    min-width: var(--ui-control-sm);
    padding-inline: 14px;
  }

  /* A small button looks 32px but takes a 40px touch: the hit area grows 4px
     above and below on touch screens, so it stays in its row's height. */
  @media (pointer: coarse) {
    .button[data-size="sm"]::after {
      content: "";
      position: absolute;
      inset: calc((var(--ui-control-sm) - var(--ui-control-md)) / 2) 0;
    }
  }

  .button[data-size="lg"] {
    height: var(--ui-control-lg);
    min-width: var(--ui-control-lg);
    padding-inline: var(--ui-space-5);
    font-size: var(--ui-text-md);
  }

  /* Hover and press mix from --button-bg and --button-fg, so overrides get
     matching shades. Filled or not, every button sits on the one control
     shadow: no glint along the top, nothing darker under the bottom edge. */
  .button[data-variant="primary"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-ink);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 92%, var(--button-fg));
    --button-bg-press: color-mix(in oklch, var(--button-bg) 85%, var(--button-fg));
    --button-fg: var(--ui-on-ink);
  }

  .button[data-variant="secondary"] {
    --button-bg: var(--ui-surface);
    --button-edge: var(--ui-border-strong);
    --button-depth: var(--ui-shadow-control);
  }

  .button[data-variant="danger"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-danger);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 93%, black);
    --button-bg-press: color-mix(in oklch, var(--button-bg) 86%, black);
    --button-fg: var(--ui-on-danger);
  }

  @media (hover: hover) {
    .button:hover:not(:disabled, [aria-busy])::before {
      background: var(--button-bg-hover);
    }
    .button[data-variant="secondary"]:hover:not(:disabled, [aria-busy])::before {
      background: var(--ui-fill-solid);
    }
  }

  .button:active:not(:disabled, [aria-busy])::before {
    --button-depth: 0 0 transparent;
    background: var(--button-bg-press);
    transition-duration: var(--ui-dur-press);
  }

  .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
    scale: var(--ui-scale-press);
  }

  .button:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .button:disabled {
    opacity: 0.5;
    cursor: default;
  }

  .button[aria-busy] {
    cursor: default;
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* Room for descenders inside the busy mask, cancelled by the negative margin.
       Always on, so turning busy on never moves the label. */
    margin: -4px -6px;
    padding: var(--ui-space-1) 6px;
  }

  .content svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    pointer-events: none;
  }

  /* Shown only once the work has lasted 300ms (use-delayed-busy.ts), so the
     shimmer starts at once when it does. */
  .button[data-busy-shown] .content {
    --button-dim: 1;
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--button-dim)) 35%,
      black 50%,
      rgb(0 0 0 / var(--button-dim)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation:
      button-dim var(--ui-dur-base) var(--ui-ease-color) forwards,
      button-sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes button-dim {
    to {
      --button-dim: 0.4;
    }
  }

  @keyframes button-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .button::before {
      transition-property: background-color, box-shadow;
    }
    .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
      scale: none;
    }
    .button[data-busy-shown] .content {
      --button-dim: 0.5;
      animation: none;
    }
  }

  /* block: the full width of its container, label still centered. */
  .button[data-block] {
    display: grid;
    width: 100%;
  }
}

"use client";

import { isValidElement, type ComponentProps, type MouseEvent, type ReactNode } from "react";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./button.module.css";
import { useDelayedBusy } from "./use-delayed-busy";

type ButtonProps = ComponentProps<"button"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Work is in flight: presses are ignored at once, focus stays. The shimmer
   *  (and `busyLabel`) shows only once it has lasted 300ms, then for 400ms at least. */
  busy?: boolean;
  /** The label while the busy state shows, like "Saving…". Morphs from the label. */
  busyLabel?: ReactNode;
  /** Fills its container's width: the main action of a narrow form or a sheet. */
  block?: boolean;
};

export function Button({
  variant = "primary",
  size = "md",
  busy = false,
  busyLabel,
  block = false,
  type = "button",
  className,
  children,
  onClick,
  ...props
}: ButtonProps) {
  const shown = useDelayedBusy(busy);
  // One element and no text, named by aria-label: an icon button, drawn as a capsule.
  const iconOnly = isValidElement(children) && Boolean(props["aria-label"]);
  const label = shown && busyLabel !== undefined ? busyLabel : children;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    // Busy is not disabled: the button keeps focus and its tab stop.
    if (busy) {
      event.preventDefault();
      return;
    }
    onClick?.(event);
  }

  return (
    <button
      type={type}
      data-variant={variant}
      data-size={size}
      data-block={block || undefined}
      aria-busy={busy || undefined}
      aria-disabled={busy || undefined}
      data-busy-shown={shown || undefined}
      data-icon-only={iconOnly || undefined}
      className={className ? `${styles.button} ${className}` : styles.button}
      onClick={handleClick}
      {...props}
    >
      <span className={styles.content}>
        {typeof label === "string" ? <TextMorph>{label}</TextMorph> : label}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Whether to show that work is running. Fast work never shows: the busy
 * state appears only once `busy` has lasted `delay` ms, and once it has
 * appeared it stays at least `minimum` ms, so it never flickers in and out.
 */
export function useDelayedBusy(busy: boolean, delay = 300, minimum = 400) {
  const [shown, setShown] = useState(false);
  const since = useRef(0);

  useEffect(() => {
    if (busy === shown) return;
    const wait = busy ? delay : Math.max(0, minimum - (performance.now() - since.current));
    const timer = window.setTimeout(() => {
      if (busy) since.current = performance.now();
      setShown(busy);
    }, wait);
    return () => window.clearTimeout(timer);
  }, [busy, shown, delay, minimum]);

  return shown;
}

@layer theme, base, components, utilities;

@layer components {
  /* Base UI's Positioner places this element; the surface inside it animates. */
  .positioner {
    z-index: 60;
    max-width: min(280px, calc(100vw - 16px));
  }

  .surface {
    position: relative;
    display: flex;
    align-items: baseline;
    gap: var(--ui-space-2);
    width: max-content;
    max-width: 100%;
    box-sizing: border-box;
    padding: var(--ui-space-1) var(--ui-space-2);
    border-radius: var(--ui-radius-sm);
    background: var(--ui-ink);
    box-shadow: var(--ui-shadow-raised);
    color: var(--ui-on-ink);
    font: var(--ui-weight-medium) var(--ui-text-sm) / var(--ui-leading-sm) var(--ui-font-sans);
    text-wrap: pretty;
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .surface[hidden] {
    display: none;
  }

  .surface[data-starting-style],
  .surface[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .surface[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  /* Warm: opened while another tooltip was showing or had just closed. */
  .surface[data-warm] {
    transition-duration: 0s;
  }

  .content {
    min-width: 0;
  }

  .kbd {
    flex-shrink: 0;
    color: var(--ui-on-ink-muted);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    /* Otherwise the mono face on the baseline makes the tooltip taller. */
    line-height: 1;
  }

  /* Base UI sets the arrow's offset along the edge; the SVG points down by default. */
  .arrow {
    position: absolute;
    width: 12px;
    height: 6px;
  }

  .arrow svg {
    display: block;
    width: 12px;
    height: 6px;
    fill: var(--ui-ink);
  }

  .arrow[data-side="top"] {
    top: 100%;
  }

  .arrow[data-side="bottom"] {
    bottom: 100%;
    rotate: 180deg;
  }

  .arrow[data-side="left"] {
    left: calc(100% - 3px);
    rotate: -90deg;
  }

  .arrow[data-side="right"] {
    right: calc(100% - 3px);
    rotate: 90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .surface {
      transition: none;
    }
    .surface[data-starting-style],
    .surface[data-ending-style] {
      scale: none;
    }
  }
}

"use client";

import {
  cloneElement,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { flushSync } from "react-dom";
import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import styles from "./tooltip.module.css";

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

/** Hover delay before the first tooltip opens. */
const OPEN_DELAY = 500;
/** After a tooltip closes, others open instantly for this long. */
const WARM_WINDOW = 300;

type Handle = { finishExit: () => void; rect: () => DOMRect | undefined };

// Shared by every tooltip on the page, so the component needs no provider.
let active: Handle | null = null;
let exiting: Handle | null = null;
let lastClosedAt = -Infinity;
// Where the previous tooltip sat, so a warm hand-off can slide from there.
let handoff: DOMRect | undefined;

function isWarm() {
  return active !== null || performance.now() - lastClosedAt < WARM_WINDOW;
}

/** A CSS time token in ms. Browsers may report "250ms" as ".25s". */
function ms(value: string, fallback: number) {
  const n = parseFloat(value);
  if (Number.isNaN(n)) return fallback;
  return value.trim().endsWith("ms") ? n : n * 1000;
}

type TriggerProps = { "aria-describedby"?: string };

type TooltipProps = {
  /** What the tooltip says; never the only place something lives. */
  content: ReactNode;
  /** A shortcut shown after the text, like "⌘C". */
  kbd?: string;
  side?: Side;
  align?: Align;
  /** Show an arrow pointing at the trigger. */
  arrow?: boolean;
  /** Link it with `aria-describedby`. Turn off when it only repeats the trigger's `aria-label`. */
  describe?: boolean;
  /** Hover delay before the first tooltip opens, in ms. */
  delay?: number;
  /** One focusable element. Disabled controls need a wrapper; see the guide. */
  children: ReactElement<TriggerProps>;
};

export function Tooltip({
  content,
  kbd,
  side = "top",
  align = "center",
  arrow = false,
  describe = true,
  delay = OPEN_DELAY,
  children,
}: TooltipProps) {
  const tipId = `${useId()}-tooltip`;
  const popupRef = useRef<HTMLDivElement>(null);
  const [triggerEl, setTriggerEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  // Read when the pointer arrives, so Base UI sees a 0ms delay while another tooltip is warm.
  const [warm, setWarm] = useState(false);
  const [instant, setInstant] = useState(false);

  const handle = useRef<Handle>({
    finishExit: () => {
      setInstant(true);
      popupRef.current?.getAnimations().forEach((a) => a.finish());
    },
    // Open or still fading out.
    rect: () => {
      const popup = popupRef.current;
      return popup && +getComputedStyle(popup).opacity > 0 ? popup.getBoundingClientRect() : undefined;
    },
  });

  function onOpenChange(next: boolean) {
    const self = handle.current;
    if (next) {
      const skipEntrance = isWarm();
      const previous = active ?? exiting;
      if (previous && previous !== self) {
        handoff = previous.rect();
        // Don't cross-fade: the outgoing one just goes.
        previous.finishExit();
      }
      active = self;
      exiting = null;
      setInstant(skipEntrance);
    } else {
      if (active === self) {
        active = null;
        lastClosedAt = performance.now();
      }
      exiting = self;
    }
    setOpen(next);
  }

  // A warm hand-off slides from where the previous tooltip sat.
  useEffect(() => {
    if (!open || !instant) return;
    const from = handoff;
    handoff = undefined;
    if (!from || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const frame = requestAnimationFrame(() => {
      const popup = popupRef.current;
      if (!popup) return;
      const to = popup.getBoundingClientRect();
      const dx = from.left + from.width / 2 - (to.left + to.width / 2);
      const dy = from.top - to.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
      const style = getComputedStyle(popup);
      popup.animate(
        { translate: [`${dx}px ${dy}px`, "0 0"] },
        {
          duration: ms(style.getPropertyValue("--ui-dur-snap"), 250),
          easing: style.getPropertyValue("--ui-ease-snap").trim() || "ease-out",
        },
      );
    });
    return () => cancelAnimationFrame(frame);
  }, [open, instant]);

  useEffect(() => {
    const self = handle.current;
    return () => {
      if (active === self) active = null;
      if (exiting === self) exiting = null;
    };
  }, []);

  const describedBy = [children.props["aria-describedby"], describe ? tipId : null].filter(Boolean).join(" ");

  return (
    <BaseTooltip.Root
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={(next) => {
        if (next) return;
        if (exiting === handle.current) exiting = null;
        setInstant(false);
      }}
    >
      <BaseTooltip.Trigger
        ref={setTriggerEl}
        delay={warm ? 0 : delay}
        // Pointer events have continuous priority; flush so the delay is in place before mouseenter.
        onPointerEnter={() => flushSync(() => setWarm(isWarm()))}
        render={cloneElement(children, { "aria-describedby": describedBy || undefined })}
      />
      {/* Kept mounted so `aria-describedby` points at real text even while closed. */}
      <BaseTooltip.Portal
        keepMounted={describe}
        container={triggerEl?.closest<HTMLElement>("dialog[open], [data-theme]") ?? undefined}
      >
        <BaseTooltip.Positioner
          className={styles.positioner}
          side={side}
          align={align}
          sideOffset={arrow ? 10 : 6}
          collisionPadding={8}
        >
          <BaseTooltip.Popup
            ref={popupRef}
            id={tipId}
            role="tooltip"
            className={styles.surface}
            data-warm={instant || undefined}
          >
            <span className={styles.content}>{content}</span>
            {kbd && <kbd className={styles.kbd}>{kbd}</kbd>}
            {arrow && (
              <BaseTooltip.Arrow className={styles.arrow}>
                <svg viewBox="0 0 12 6" aria-hidden="true">
                  <path d="M0 0h12L7.2 5.1a1.6 1.6 0 0 1-2.4 0z" />
                </svg>
              </BaseTooltip.Arrow>
            )}
          </BaseTooltip.Popup>
        </BaseTooltip.Positioner>
      </BaseTooltip.Portal>
    </BaseTooltip.Root>
  );
}

/* The pill's flight from one item to the next, shared by Tabs and the
   Segmented control so the two move as one family. The resting position is
   the caller's; this plays the move between two spans on top of it. */

/** A pill's offset and length along its track, and how far it's dipped. */
export type PillSpan = { start: number; length: number; dip?: number };

/** How deep the pill dips mid-flight, in px: none. A dip (and a spring on
 *  the leading edge) read as organic, a blob more than a control. */
const MAX_DIP = 0;

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

/** A `linear(...)` easing token as a function of progress, for sampling in JS. */
function curve(value: string): (t: number) => number {
  const points = value.startsWith("linear(") ? value.slice(7, -1).split(",").map(parseFloat) : [];
  if (points.length < 2 || points.some(Number.isNaN)) return (t) => 1 - (1 - t) ** 3;
  return (t) => {
    const at = Math.min(Math.max(t, 0), 1) * (points.length - 1);
    const i = Math.min(Math.floor(at), points.length - 2);
    return points[i] + (points[i + 1] - points[i]) * (at - i);
  };
}

/** Where the pill is along its track right now, mid-animation included. */
function translated(el: HTMLElement, vertical: boolean) {
  const transform = getComputedStyle(el).transform;
  if (!transform || transform === "none") return 0;
  const matrix = new DOMMatrixReadOnly(transform);
  return vertical ? matrix.m42 : matrix.m41;
}

/** Stops a flight in progress and returns where it left the pill on screen, or null if it was still. */
export function stopPill(indicator: HTMLElement, vertical = false): PillSpan | null {
  const running = indicator.getAnimations();
  if (!running.length) return null;
  const box = indicator.getBoundingClientRect();
  const span = {
    start: translated(indicator, vertical),
    length: vertical ? box.height : box.width,
    dip: Math.max(0, vertical ? indicator.offsetWidth - box.width : indicator.offsetHeight - box.height),
  };
  running.forEach((a) => a.cancel());
  return span;
}

/**
 * Flies the pill from one span to another: the edge facing the new item
 * leads, the far edge follows, both on the glide (no overshoot), so the
 * pill stretches a little toward the new item and settles once. Length
 * animates, not scale, which would squash the round ends. Under reduced
 * motion it doesn't play.
 */
export function flyPill(indicator: HTMLElement, from: PillSpan, to: PillSpan, vertical = false) {
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const duration = ms(token(indicator, "--ui-dur-glide", "320ms"));
  const lead = curve(token(indicator, "--ui-ease-glide", ""));
  const follow = curve(token(indicator, "--ui-ease-glide", ""));
  const leadShare = ms(token(indicator, "--ui-dur-snap", "250ms")) / duration;
  const forward = to.start > from.start;
  const fromDip = from.dip ?? 0;
  // The dip only ever shrinks the pill, so nothing pokes out of the track.
  const full = vertical ? indicator.offsetWidth : indicator.offsetHeight;
  const travel = Math.abs(to.start + to.length / 2 - (from.start + from.length / 2));
  const dip = Math.min(MAX_DIP, travel / 30);
  const frames: Keyframe[] = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const fast = lead(Math.min(t / leadShare, 1));
    const slow = follow(t);
    const near = from.start + (to.start - from.start) * (forward ? slow : fast);
    const far = from.start + from.length + (to.start + to.length - from.start - from.length) * (forward ? fast : slow);
    const p = Math.min(Math.max((fast + slow) / 2, 0), 1);
    const d = fromDip * (1 - p) + dip * Math.sin(Math.PI * p);
    frames.push(
      vertical
        ? { transform: `translate(${d / 2}px, ${near}px)`, height: `${far - near}px`, width: `${full - d}px` }
        : { transform: `translate(${near}px, ${d / 2}px)`, width: `${far - near}px`, height: `${full - d}px` },
    );
  }
  indicator.animate(frames, { duration, easing: "linear" });
}

@layer theme, base, components, utilities;

.pause {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .tabs {
    display: grid;
    gap: var(--ui-space-4);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .list {
    position: relative;
    isolation: isolate;
    display: flex;
    justify-self: start;
    max-width: 100%;
    /* The track the Segmented control shares: --ui-track-* in the tokens. */
    padding: var(--ui-track-inset);
    border-radius: var(--ui-radius-full);
    box-shadow: var(--ui-track-edge);
    overflow-x: auto;
    /* Also blocks the browser's back-swipe gesture. */
    overscroll-behavior-inline: none;
    /* Keeps a selected tab scrolled clear of the edge fade. */
    scroll-padding-inline: var(--ui-space-6);
    scrollbar-width: none;
  }

  .list::-webkit-scrollbar {
    display: none;
  }

  .list[data-overflow-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-end] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-start] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start][data-overflow-end] {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--ui-space-6),
      black calc(100% - var(--ui-space-6)),
      transparent
    );
  }

  /* Base UI's Indicator places it on the selected tab through its CSS
     variables; the flight between tabs is a script animation on top. */
  .indicator {
    position: absolute;
    top: var(--ui-track-inset);
    left: 0;
    z-index: -1;
    width: var(--active-tab-width);
    height: var(--ui-control-sm);
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    transform: translateX(var(--active-tab-left));
    contain: strict;
    pointer-events: none;
  }

  .tab {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    flex-shrink: 0;
    height: var(--ui-control-sm);
    padding-inline: 14px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    /* One weight for every state: bolding the selected tab would widen it. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] {
    color: var(--ui-foreground);
  }

  /* Until the Indicator has measured, the selected tab carries the pill itself. */
  .list:not(:has(> .indicator:not([hidden]))) .tab[data-active] {
    background: var(--ui-track-pill);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) {
      color: var(--ui-foreground);
    }
  }

  .tab:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .tab svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    pointer-events: none;
  }

  /* ---------- Count ---------- */

  .count {
    color: var(--ui-subtle);
    font-weight: var(--ui-weight-regular);
    font-variant-numeric: tabular-nums;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] .count {
    color: var(--ui-muted);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) .count {
      color: var(--ui-muted);
    }
  }

  @media (pointer: coarse) {
    .tab::after {
      content: "";
      position: absolute;
      inset: -4px 0;
    }
  }

  /* ---------- Vertical ---------- */

  /* The 480px container breakpoint below must match the script, which reads
     the axis from the layout. */
  .tabs[data-layout="vertical"] {
    container-type: inline-size;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: var(--ui-space-6);
    align-items: start;
  }

  .tabs[data-layout="vertical"] > * {
    grid-column: 1 / -1;
  }

  @container (width >= 480px) {
    .tabs[data-layout="vertical"] > * {
      grid-column: auto;
    }

    .tabs[data-layout="vertical"] > .list {
      flex-direction: column;
      justify-self: stretch;
      min-width: 160px;
      padding: 0;
      border-radius: 0;
      box-shadow: none;
      overflow: visible;
      mask-image: none;
    }

    .tabs[data-layout="vertical"] > .list > .indicator {
      top: 0;
      width: 100%;
      height: var(--active-tab-height);
      transform: translateY(var(--active-tab-top));
    }

    .tabs[data-layout="vertical"] > .list > .tab {
      justify-content: flex-start;
    }

    .tabs[data-layout="vertical"] > .list > .tab > .count {
      margin-inline-start: auto;
      padding-inline-start: var(--ui-space-3);
    }

    /* Rows touch, so the hit area can't extend past them; the row grows instead. */
    @media (pointer: coarse) {
      .tabs[data-layout="vertical"] > .list > .tab {
        height: 40px;
      }
      .tabs[data-layout="vertical"] > .list > .tab::after {
        inset: 0;
      }
    }
  }

  .panel {
    min-width: 0;
    border-radius: var(--ui-radius-md);
  }

  .panel:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .panels {
    display: grid;
  }

  .panel[data-crossfade] {
    grid-area: 1 / 1;
    /* Base UI marks unselected panels hidden; here they still hold the cell. */
    display: block;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .panel[data-crossfade][data-selected] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    .panel[data-crossfade],
    .panel[data-crossfade][data-selected] {
      transition: none;
    }
  }
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { DirectionProvider } from "@base-ui/react/direction-provider";
import { TextMorph } from "../text-morph/text-morph";
import { flyPill, stopPill } from "./pill-flight";
import styles from "./tabs.module.css";

type Orientation = "horizontal" | "vertical";

type TabsContextValue = {
  value: string;
  crossfade: boolean;
  manual: boolean;
  setAxis: (axis: Orientation) => void;
  register: (value: string) => () => void;
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string) {
  const context = useContext(TabsContext);
  if (!context) throw new Error(`<${part}> must be inside <Tabs>.`);
  return context;
}

type TabsProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** Controlled value. Pair with `onValueChange`. */
  value?: string;
  /** Uncontrolled starting value, used when the URL has no valid `param`. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Arrow keys move focus only; Enter or Space selects. Use when showing a panel is slow. */
  manual?: boolean;
  /** Stack panels in one cell and crossfade between them. */
  crossfade?: boolean;
  /** Keep the selected tab in this search param (`?tab=notes`). Uncontrolled only. */
  param?: string;
  /** `vertical` puts the tabs in a column beside the panels; under 480px wide it falls back to a row. */
  orientation?: Orientation;
};

export function Tabs({
  value: controlledValue,
  defaultValue,
  onValueChange,
  manual = false,
  crossfade = false,
  param,
  orientation = "horizontal",
  className,
  children,
  ...props
}: TabsProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? "");
  const value = controlledValue ?? uncontrolledValue;
  const controlled = controlledValue !== undefined;
  // The axis the list is laid out on now. A vertical list falls back to a row
  // under 480px, and Base UI's arrow keys follow what's on screen.
  const [axis, setAxis] = useState<Orientation>(orientation);

  // Tabs register their values so a URL can't select a tab that doesn't exist.
  const values = useRef(new Set<string>());
  const register = useCallback((v: string) => {
    values.current.add(v);
    return () => {
      values.current.delete(v);
    };
  }, []);

  const select = useCallback(
    (next: string) => {
      if (!controlled) setUncontrolledValue(next);
      onValueChange?.(next);
      if (param && !controlled) {
        const url = new URL(window.location.href);
        url.searchParams.set(param, next);
        window.history.replaceState(window.history.state, "", url);
      }
    },
    [controlled, onValueChange, param],
  );

  // A layout effect, so children's have run and every tab is registered.
  useLayoutEffect(() => {
    if (!param || controlled) return;
    function sync() {
      const fromUrl = new URLSearchParams(window.location.search).get(param!);
      setUncontrolledValue(fromUrl && values.current.has(fromUrl) ? fromUrl : (defaultValue ?? ""));
    }
    sync();
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [param, controlled, defaultValue]);

  return (
    <TabsContext value={{ value, crossfade, manual, setAxis, register }}>
      <BaseTabs.Root
        // Always controlled: the URL and `param` live here, not in Base UI.
        value={value === "" ? null : value}
        onValueChange={(next, details) => {
          // Only user picks; ignore Base UI's own fallbacks for missing tabs.
          if (details.reason !== "none" || typeof next !== "string") return;
          select(next);
        }}
        orientation={axis}
        className={className ? `${styles.tabs} ${className}` : styles.tabs}
        data-layout={orientation}
        {...props}
      >
        {children}
      </BaseTabs.Root>
    </TabsContext>
  );
}

type TabListProps = Omit<ComponentProps<"div">, "role"> & {
  /** Names the set of tabs for screen readers, e.g. "Estimate sections". */
  "aria-label"?: string;
  "aria-labelledby"?: string;
};

/** The axis the list is laid out on now: read, not assumed, since the CSS can fall back to a row. */
function axisOf(list: HTMLElement): Orientation {
  return getComputedStyle(list).flexDirection.startsWith("column") ? "vertical" : "horizontal";
}

/** A tab's offset and length along the list, measured the way Base UI places the indicator. */
function span(tab: HTMLElement, list: HTMLElement, vertical: boolean) {
  const t = tab.getBoundingClientRect();
  const l = list.getBoundingClientRect();
  return vertical
    ? { start: t.top - l.top + list.scrollTop - list.clientTop, length: t.height }
    : { start: t.left - l.left + list.scrollLeft - list.clientLeft, length: t.width };
}

export function TabList({ className, children, ...props }: TabListProps) {
  const { value, manual, setAxis } = useTabs("TabList");
  const listRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const [direction, setDirection] = useState<"ltr" | "rtl">("ltr");
  const previous = useRef<string | null>(null);
  // Nothing animates until the first paint, so a tab picked from the URL is simply there.
  const painted = useRef(false);
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        painted.current = true;
      });
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  // Base UI's Indicator rests the pill on the selected tab through its CSS
  // variables. On a change of tab, this plays the flight between them on top.
  useLayoutEffect(() => {
    const list = listRef.current;
    const indicator = indicatorRef.current;
    const from = previous.current;
    previous.current = value;
    if (!list || !indicator || from === null || from === value) return;
    const tab = list.querySelector<HTMLElement>('[role="tab"][data-active]');
    const last = Array.from(list.querySelectorAll<HTMLElement>('[role="tab"]')).find((t) => t.dataset.value === from);
    if (!tab || !last) return;

    const vertical = axisOf(list) === "vertical";
    // A change mid-move starts from where the pill is on screen.
    const origin = stopPill(indicator, vertical) ?? span(last, list, vertical);
    if (!painted.current) return;
    flyPill(indicator, origin, span(tab, list, vertical), vertical);
  }, [value]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    setAxis(axisOf(list));
    setDirection(getComputedStyle(list).direction === "rtl" ? "rtl" : "ltr");
  }, [setAxis]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    let frame = 0;
    const edges = () => {
      const max = list.scrollWidth - list.clientWidth;
      const start = Math.abs(list.scrollLeft);
      list.toggleAttribute("data-overflow-start", start > 1);
      list.toggleAttribute("data-overflow-end", max - start > 1);
    };
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setAxis(axisOf(list)));
      edges();
    });
    observer.observe(list);
    // The scrollbar is hidden, so a vertical wheel scrolls the tabs; at either
    // end it goes back to scrolling the page.
    const wheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.shiftKey || Math.abs(event.deltaX) >= Math.abs(event.deltaY)) return;
      const max = list.scrollWidth - list.clientWidth;
      if (max <= 1) return;
      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? list.clientWidth : 1;
      const rtl = getComputedStyle(list).direction === "rtl";
      const by = event.deltaY * unit * (rtl ? -1 : 1);
      const start = Math.abs(list.scrollLeft);
      if ((by > 0) !== rtl ? max - start <= 1 : start <= 1) return;
      event.preventDefault();
      list.scrollBy({ left: by });
    };
    list.addEventListener("scroll", edges, { passive: true });
    list.addEventListener("wheel", wheel, { passive: false });
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      list.removeEventListener("scroll", edges);
      list.removeEventListener("wheel", wheel);
    };
  }, [setAxis]);

  return (
    <DirectionProvider direction={direction}>
      <BaseTabs.List
        ref={listRef}
        activateOnFocus={!manual}
        className={className ? `${styles.list} ${className}` : styles.list}
        {...props}
      >
        <BaseTabs.Indicator ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
        {children}
      </BaseTabs.List>
    </DirectionProvider>
  );
}

type TabProps = Omit<ComponentProps<"button">, "value" | "role"> & {
  value: string;
  children: ReactNode;
  /** A count after the label, read as part of the tab's name ("Guests, 14"). */
  count?: number | string;
};

export function Tab({ value, count, className, children, onFocus, ...props }: TabProps) {
  const { register } = useTabs("Tab");

  useLayoutEffect(() => register(value), [register, value]);

  return (
    <BaseTabs.Tab
      value={value}
      data-value={value}
      className={className ? `${styles.tab} ${className}` : styles.tab}
      onFocus={(event) => {
        onFocus?.(event);
        // Arrowing to a tab hidden past the fade scrolls it into view.
        if (event.currentTarget.matches(":focus-visible")) {
          event.currentTarget.scrollIntoView({ block: "nearest", inline: "nearest" });
        }
      }}
      {...props}
    >
      {count === undefined || count === "" ? (
        children
      ) : (
        <>
          <span className={styles.label}>
            {children}
            {/* Screen-reader-only pause, so the name reads "Guests, 14". */}
            <span className={styles.pause}>,</span>
          </span>
          <span className={styles.count}>
            <TextMorph>{String(count)}</TextMorph>
          </span>
        </>
      )}
    </BaseTabs.Tab>
  );
}

type TabPanelProps = Omit<ComponentProps<"div">, "role"> & {
  value: string;
};

export function TabPanel({ value, className, children, ...props }: TabPanelProps) {
  const { value: selected, crossfade } = useTabs("TabPanel");
  return (
    <BaseTabs.Panel
      value={value}
      // Unselected panels stay mounted, so their state survives a switch.
      keepMounted
      data-crossfade={crossfade || undefined}
      data-selected={value === selected || undefined}
      className={className ? `${styles.panel} ${className}` : styles.panel}
      {...props}
    >
      {children}
    </BaseTabs.Panel>
  );
}

/** Wraps the panels when `crossfade` is on, so they share one grid cell. */
export function TabPanels({ className, ...props }: ComponentProps<"div">) {
  return <div className={className ? `${styles.panels} ${className}` : styles.panels} {...props} />;
}

@layer theme, base, components, utilities;

.content {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* The whole control, track included, is a control height: --segmented-h.
     The options sit inside it, --segmented-pad from every edge. Track, pill
     and inset are the Tabs' own (--ui-track-* in the tokens): the two share
     one look and differ only in what they mean. */
  .root {
    --segmented-h: var(--ui-control-md);
    --segmented-pad: var(--ui-track-inset);
    --segmented-option: calc(var(--segmented-h) - var(--segmented-pad) * 2);
    position: relative;
    isolation: isolate;
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(max-content, 1fr);
    max-width: 100%;
    /* Labels stay whole, so in a container too narrow for them the options
       scroll sideways inside the track instead of pushing the page. */
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
    padding: var(--segmented-pad);
    border-radius: var(--ui-radius-full);
    box-shadow: var(--ui-track-edge);
    font-family: var(--ui-font-sans);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  /* Tabs come in one size. At sm a 4px inset would leave a 24px pill too
     tight around its label, so the inset drops by 1px; all else is shared. */
  .root[data-size="sm"] {
    --segmented-h: var(--ui-control-sm);
    --segmented-pad: calc(var(--ui-track-inset) - 1px);
  }

  .root[data-size="sm"] .option {
    padding-inline: 12px;
    font-size: var(--ui-text-sm);
  }

  .root[data-widths="content"] {
    grid-auto-columns: auto;
  }

  .indicator {
    position: absolute;
    top: var(--segmented-pad);
    left: 0;
    z-index: -1;
    height: var(--segmented-option);
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    contain: strict;
    pointer-events: none;
    visibility: hidden;
  }

  .root[data-ready] .indicator[data-visible] {
    visibility: visible;
  }

  .option {
    position: relative;
    display: grid;
    place-items: center;
    min-width: 0;
    height: var(--segmented-option);
    padding-inline: 14px;
    border-radius: var(--ui-radius-full);
    color: var(--ui-muted);
    /* One weight in every state, so selecting never changes a width. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .option[data-checked] {
    color: var(--ui-foreground);
  }

  /* Until the pill has measured, the checked option carries it itself. */
  .root:not([data-ready]) .option[data-checked] {
    background: var(--ui-track-pill);
  }

  @media (hover: hover) {
    .option:hover:not([data-checked], [data-disabled]) {
      color: var(--ui-foreground);
    }
  }

  .option:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* A label with a count beside it stays on one line, like any other. */
    white-space: nowrap;
    pointer-events: none;
  }

  .content svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
  }

  .option[data-disabled] {
    opacity: 0.5;
    cursor: default;
  }

  @media (pointer: coarse) {
    .option::after {
      content: "";
      position: absolute;
      inset: -4px 0;
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { flyPill, stopPill } from "../tabs/pill-flight";
import styles from "./segmented-control.module.css";

type SegmentedControlProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "role"> & {
  /** Accessible name of the group. */
  "aria-label"?: string;
  "aria-labelledby"?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** `equal`: every option as wide as the widest. `content`: each as wide as its label. */
  widths?: "equal" | "content";
  /** Form field name. */
  name?: string;
  disabled?: boolean;
  /** Outer height, track included: `sm` matches a small button or select, `md` a default one. */
  size?: "sm" | "md";
};

/** A Base UI radio group with one pill that glides to the checked option, as the Tabs pill does. */
export function SegmentedControl({
  value: controlledValue,
  defaultValue,
  onValueChange,
  widths = "equal",
  size = "md",
  name,
  disabled = false,
  className,
  children,
  ...props
}: SegmentedControlProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? "");
  const value = controlledValue ?? uncontrolledValue;

  const select = useCallback(
    (next: string) => {
      if (controlledValue === undefined) setUncontrolledValue(next);
      onValueChange?.(next);
    },
    [controlledValue, onValueChange],
  );

  const rootRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const placed = useRef<{ value: string; x: number; width: number } | null>(null);
  const painted = useRef(false);
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        painted.current = true;
      });
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  const place = useCallback(
    (animate: boolean) => {
      const root = rootRef.current;
      const indicator = indicatorRef.current;
      const option = root?.querySelector<HTMLElement>(`[data-value="${CSS.escape(value)}"]`);
      if (!root || !indicator) return;
      if (!option) {
        indicator.removeAttribute("data-visible");
        placed.current = null;
        return;
      }

      // Not offsetLeft: it rounds, and equal-width options rarely land on whole pixels.
      const box = option.getBoundingClientRect();
      // Plus the scroll, for a control that scrolls sideways in a narrow container.
      const x = box.left - root.getBoundingClientRect().left + root.scrollLeft;
      const width = box.width;
      const last = placed.current;
      indicator.setAttribute("data-visible", "");
      if (last && last.value === value && last.x === x && last.width === width) return;

      // A change mid-move starts from where the pill is on screen.
      const origin = stopPill(indicator) ?? (last ? { start: last.x, length: last.width } : null);
      indicator.style.transform = `translateX(${x}px)`;
      indicator.style.width = `${width}px`;
      placed.current = { value, x, width };

      const moved = last && last.value !== value;
      if (!animate || !moved || !origin || !painted.current) return;
      // The same flight as the Tabs pill: stretch, dip and draw in.
      flyPill(indicator, origin, { start: x, length: width });
    },
    [value],
  );

  useLayoutEffect(() => {
    place(true);
    rootRef.current?.setAttribute("data-ready", "");
  }, [place]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let frame = 0;
    const remeasure = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => place(false));
    };
    const observer = new ResizeObserver(remeasure);
    observer.observe(root);
    for (const option of root.querySelectorAll("[data-value]")) observer.observe(option);
    document.fonts?.ready.then(remeasure);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [place]);

  return (
    <BaseRadioGroup
      ref={rootRef}
      value={value}
      onValueChange={(next) => select(next as string)}
      name={name}
      disabled={disabled}
      data-widths={widths}
      data-size={size}
      className={className ? `${styles.root} ${className}` : styles.root}
      {...props}
    >
      <span ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
      {children}
    </BaseRadioGroup>
  );
}

type SegmentProps = Omit<ComponentProps<"span">, "children" | "role"> & {
  value: string;
  children: ReactNode;
  disabled?: boolean;
};

/** One option. For an icon-only option, pass `aria-label`. */
export function Segment({ value, children, disabled, className, ...props }: SegmentProps) {
  return (
    <BaseRadio.Root
      value={value}
      disabled={disabled}
      data-value={value}
      className={className ? `${styles.option} ${className}` : styles.option}
      {...props}
    >
      <span className={styles.content}>{children}</span>
    </BaseRadio.Root>
  );
}

/*
 * No "use client": this renders on the server, in <head>, so the stored theme
 * is on <html> before the first paint. A client component would render a
 * <script> React never runs, and React warns about it.
 */

/** Where the chosen theme is kept in localStorage, unless you pass another key. */
export const THEME_STORAGE_KEY = "theme";

/**
 * The inline script as a string, for frameworks that take one. It sets
 * `data-theme` on <html> to "light" or "dark": the stored choice, or the
 * system's when there is none, and follows the system while it is "system".
 */
export function themeScript(storageKey: string = THEME_STORAGE_KEY) {
  return `(function(k){var d=document.documentElement,q=matchMedia("(prefers-color-scheme: dark)");function a(){var m;try{m=localStorage.getItem(k)}catch(e){}d.dataset.theme=m==="light"||m==="dark"?m:q.matches?"dark":"light"}a();q.addEventListener("change",a)})(${JSON.stringify(storageKey)})`;
}

/** Put in <head>, before anything that paints. */
export function ThemeScript({ storageKey = THEME_STORAGE_KEY, nonce }: { storageKey?: string; nonce?: string }) {
  return <script nonce={nonce} dangerouslySetInnerHTML={{ __html: themeScript(storageKey) }} />;
}

@layer theme, base, components, utilities;

@layer components {
  /* --moon is 0 for the sun and 1 for the moon; every shape is drawn from it,
     so the two states are one drawing and only the number changes. */
  .toggle {
    --moon: 0;
  }

  /* After hydration the button carries its state. Before it, the state comes
     from <html data-theme> (set by ThemeScript before paint), so the icon is
     right on the first frame and never flips when React takes over. */
  .toggle[data-state="dark"],
  :global(html[data-theme="dark"]) .toggle:not([data-state]) {
    --moon: 1;
  }

  /* No script at all: the system's theme. */
  @media (prefers-color-scheme: dark) {
    :global(html:not([data-theme])) .toggle:not([data-state]) {
      --moon: 1;
    }
  }

  .glyph {
    overflow: visible;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* The outline is drawn as filled circles: the outer edge filled, the inner
     edge masked away, half a stroke either side of each line. */
  .glyph circle {
    --half: calc(var(--ui-icon-stroke, 1.5) * 0.5px);
    stroke: none;
  }

  /* The one circle that paints; the rest are mask. */
  .ring {
    fill: currentColor;
  }

  /* The sun's disc, which grows into the moon. */
  .disc {
    --r: calc(2.75px + 3px * var(--moon));
    cx: 8px;
    cy: 8px;
  }

  /* The circle that bites the crescent out: off the top right for the sun,
     over the disc for the moon. */
  .bite {
    --r: 4.5px;
    cx: 11.25px;
    cy: 4.75px;
    transform: translate(calc(4.5px - 4.5px * var(--moon)), calc(4.5px * var(--moon) - 4.5px));
  }

  .outer {
    r: calc(var(--r) + var(--half));
  }

  .inner {
    r: calc(var(--r) - var(--half));
  }

  .rays {
    transform-box: view-box;
    transform-origin: 8px 8px;
    rotate: calc(45deg * var(--moon));
    scale: calc(1 - 0.5 * var(--moon));
    opacity: calc(1 - var(--moon));
  }

  /* Disc and bite glide: what a track holds lands without passing its mark,
     so the crescent never over-bites and springs back. */
  .toggle[data-state] .disc {
    transition: r var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .toggle[data-state] .bite {
    transition: transform var(--ui-dur-glide) var(--ui-ease-glide);
  }

  /* To the moon the rays turn and pull in as they fade, out of the way first. */
  .toggle[data-state="dark"] .rays {
    transition:
      rotate var(--ui-dur-base) var(--ui-ease-exit),
      scale var(--ui-dur-base) var(--ui-ease-exit),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Back to the sun they come out once the disc has shrunk a little, on the snap. */
  .toggle[data-state="light"] .rays {
    transition:
      rotate var(--ui-dur-snap) var(--ui-ease-snap) var(--ui-dur-press),
      scale var(--ui-dur-snap) var(--ui-ease-snap) var(--ui-dur-press),
      opacity var(--ui-dur-fast) var(--ui-ease-color) var(--ui-dur-press);
  }

  /* Reduced motion: no shape moves; the new icon fades in where the old one was. */
  @media (prefers-reduced-motion: reduce) {
    .toggle[data-state] :is(.disc, .bite, .rays) {
      transition: none;
    }
    .toggle[data-changed][data-state="dark"] .glyph {
      animation: fade-to-moon var(--ui-dur-base) var(--ui-ease-color);
    }
    .toggle[data-changed][data-state="light"] .glyph {
      animation: fade-to-sun var(--ui-dur-base) var(--ui-ease-color);
    }
  }

  /* Two names for one fade, so each change restarts it. */
  @keyframes fade-to-moon {
    from {
      opacity: 0;
    }
  }

  @keyframes fade-to-sun {
    from {
      opacity: 0;
    }
  }

  /* The page crossfades while the theme changes (useTheme's setTheme). Every
     snapshot holds still and the new one fades in over the old, with no
     additive blend, so nothing flashes brighter mid-way. */
  :global(:root:active-view-transition-type(theme)::view-transition-group(*)) {
    animation: none;
  }

  :global(:root:active-view-transition-type(theme)::view-transition-old(*)) {
    display: block;
    animation: none;
  }

  :global(:root:active-view-transition-type(theme)::view-transition-new(*)) {
    animation: theme-in var(--ui-dur-base) var(--ui-ease-color) both;
    mix-blend-mode: normal;
  }

  @keyframes theme-in {
    from {
      opacity: 0;
    }
  }
}

"use client";

import { useCallback, useEffect, useId, useState, useSyncExternalStore, type ComponentProps } from "react";
import { Button } from "../button/button";
import { Segment, SegmentedControl } from "../segmented-control/segmented-control";
import { Tooltip } from "../tooltip/tooltip";
import { THEME_STORAGE_KEY } from "./theme-script";
import styles from "./theme-toggle.module.css";

// ThemeScript and themeScript() live in ./theme-script, which has no "use
// client": imported from here, a server layout would get a client reference.

/** What the person chose. "system" follows the OS. */
export type Theme = "light" | "dark" | "system";
/** What is on screen. */
export type ResolvedTheme = "light" | "dark";

const QUERY = "(prefers-color-scheme: dark)";
/** Same-tab writes; `storage` only fires in other tabs. */
const CHANGE = "uipolish:theme";

function readStored(key: string): Theme {
  try {
    const value = localStorage.getItem(key);
    return value === "light" || value === "dark" ? value : "system";
  } catch {
    return "system";
  }
}

function readSystem(): ResolvedTheme {
  return matchMedia(QUERY).matches ? "dark" : "light";
}

/** The theme on <html>, or the system's when nothing is forced. */
function readResolved(): ResolvedTheme {
  const forced = document.documentElement.dataset.theme;
  return forced === "light" || forced === "dark" ? forced : readSystem();
}

function apply(theme: Theme) {
  const resolved = theme === "system" ? readSystem() : theme;
  const root = document.documentElement;
  if (root.dataset.theme !== resolved) root.dataset.theme = resolved;
}

type TransitionDocument = Document & {
  startViewTransition?: (options: { update: () => void; types: string[] }) => unknown;
};

/** A quick crossfade of the whole page, where view transition types exist. */
function withTransition(update: () => void) {
  const doc = document as TransitionDocument;
  if (!doc.startViewTransition || matchMedia("(prefers-reduced-motion: reduce)").matches) return update();
  try {
    // Browsers with view transitions but without types take only a callback and throw here.
    doc.startViewTransition({ update, types: ["theme"] });
  } catch {
    update();
  }
}

function subscribe(onChange: () => void) {
  const media = matchMedia(QUERY);
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  media.addEventListener("change", onChange);
  window.addEventListener("storage", onChange);
  window.addEventListener(CHANGE, onChange);
  return () => {
    observer.disconnect();
    media.removeEventListener("change", onChange);
    window.removeEventListener("storage", onChange);
    window.removeEventListener(CHANGE, onChange);
  };
}

const unknown = () => undefined;

/** The OS's theme, following it live. Undefined until hydration. */
export function useSystemTheme() {
  return useSyncExternalStore(subscribe, readSystem, unknown);
}

type UseThemeOptions = {
  /** localStorage key. Match it in `ThemeScript`. */
  storageKey?: string;
  /** Crossfade the page when the theme changes (never under reduced motion). */
  transition?: boolean;
};

/** The document's theme. Every value is undefined until hydration. */
function useDocumentTheme({ storageKey = THEME_STORAGE_KEY, transition = true }: UseThemeOptions, active: boolean) {
  const readTheme = useCallback(() => readStored(storageKey), [storageKey]);
  const theme = useSyncExternalStore(subscribe, readTheme, unknown);
  const resolvedTheme = useSyncExternalStore(subscribe, readResolved, unknown);
  const systemTheme = useSystemTheme();

  // Without ThemeScript, or after another tab or the OS changes it.
  useEffect(() => {
    if (!active) return;
    const sync = () => apply(readStored(storageKey));
    const onStorage = (e: StorageEvent) => {
      if (e.key === storageKey || e.key === null) sync();
    };
    sync();
    const media = matchMedia(QUERY);
    media.addEventListener("change", sync);
    window.addEventListener("storage", onStorage);
    return () => {
      media.removeEventListener("change", sync);
      window.removeEventListener("storage", onStorage);
    };
  }, [active, storageKey]);

  const setTheme = useCallback(
    (next: Theme) => {
      try {
        if (next === "system") localStorage.removeItem(storageKey);
        else localStorage.setItem(storageKey, next);
      } catch {
        // Private mode: the theme still changes for this page.
      }
      window.dispatchEvent(new Event(CHANGE));
      const update = () => apply(next);
      if (transition) withTransition(update);
      else update();
    },
    [storageKey, transition],
  );

  return { theme, resolvedTheme, systemTheme, setTheme };
}

/**
 * The page's theme: what was chosen, what is showing, and a setter that
 * stores it and sets `data-theme` on <html>. Values are undefined until
 * hydration, so the server and the first client render agree.
 */
export function useTheme(options: UseThemeOptions = {}) {
  return useDocumentTheme(options, true);
}

type ThemeToggleProps = Omit<ComponentProps<"button">, "value" | "children"> & {
  /** Controlled: the theme this button shows. Leave it out to drive the page (`useTheme`). */
  value?: Theme;
  /** The theme it switches to. */
  onValueChange?: (theme: ResolvedTheme) => void;
  size?: "sm" | "md";
  variant?: "ghost" | "secondary";
  /** Show the next theme in a tooltip. */
  tooltip?: boolean;
  tooltipSide?: "top" | "bottom" | "left" | "right";
} & UseThemeOptions;

/** One capsule that switches light and dark; its sun turns into a moon. */
export function ThemeToggle({
  value,
  onValueChange,
  size = "md",
  variant = "ghost",
  tooltip = true,
  tooltipSide = "bottom",
  storageKey,
  transition,
  onClick,
  className,
  "aria-label": label = "Dark theme",
  ...props
}: ThemeToggleProps) {
  const controlled = value !== undefined;
  const page = useDocumentTheme({ storageKey, transition }, !controlled);
  const system = useSystemTheme();
  const resolved = controlled ? (value === "system" ? system : value) : page.resolvedTheme;
  const next: ResolvedTheme = resolved === "dark" ? "light" : "dark";

  // Fade (reduced motion) only on a real change, never on hydration.
  const [shown, setShown] = useState(resolved);
  const [changed, setChanged] = useState(false);
  if (resolved !== shown) {
    setShown(resolved);
    if (shown !== undefined && resolved !== undefined) setChanged(true);
  }

  const button = (
    <Button
      variant={variant}
      size={size}
      aria-label={label}
      aria-pressed={resolved === undefined ? undefined : resolved === "dark"}
      // Until hydration there's no state: CSS draws it from <html data-theme>.
      data-state={resolved}
      data-changed={changed || undefined}
      className={className ? `${styles.toggle} ${className}` : styles.toggle}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || resolved === undefined) return;
        onValueChange?.(next);
        // Back to the OS's theme means following the OS again.
        if (!controlled) page.setTheme(next === page.systemTheme ? "system" : next);
      }}
      {...props}
    >
      <Glyph />
    </Button>
  );

  if (!tooltip) return button;
  return (
    <Tooltip
      side={tooltipSide}
      describe={false}
      content={resolved === undefined ? "Switch theme" : `Switch to ${next} theme`}
    >
      {button}
    </Tooltip>
  );
}

// Eight short rays on a 16px grid, 5.25 to 6.75 from the center.
const RAYS = Array.from({ length: 8 }, (_, i) => {
  const a = (i * Math.PI) / 4;
  const p = (r: number) => `${+(8 + r * Math.cos(a)).toFixed(3)} ${+(8 + r * Math.sin(a)).toFixed(3)}`;
  return `M${p(5.25)}L${p(6.75)}`;
});

/**
 * One drawing for both themes, as an outline made of filled circles so the
 * crescent's tips come to clean points. The disc grows into the moon while a
 * second circle slides over it on the mask and bites the crescent out. The
 * rays turn, pull in and fade.
 */
function Glyph() {
  const mask = `${useId()}-moon`;
  return (
    <svg viewBox="0 0 16 16" className={styles.glyph} aria-hidden="true">
      <defs>
        {/* Hidden: the disc's inside, and the bite. The bite's own edge
            stays, so the crescent has an inner line as thick as its outer. */}
        <mask id={mask} maskUnits="userSpaceOnUse" x="-8" y="-8" width="32" height="32">
          <rect x="-8" y="-8" width="32" height="32" fill="white" />
          <circle className={`${styles.disc} ${styles.inner}`} fill="black" />
          <circle className={`${styles.bite} ${styles.outer}`} fill="white" />
          <circle className={`${styles.bite} ${styles.inner}`} fill="black" />
        </mask>
      </defs>
      <g className={styles.rays}>
        {RAYS.map((d) => (
          <path key={d} d={d} />
        ))}
      </g>
      <circle className={`${styles.disc} ${styles.outer} ${styles.ring}`} mask={`url(#${mask})`} />
    </svg>
  );
}

type ThemeSelectProps = Omit<
  ComponentProps<typeof SegmentedControl>,
  "value" | "defaultValue" | "onValueChange" | "children"
> & {
  /** Controlled. Leave it out to drive the page (`useTheme`). */
  value?: Theme;
  onValueChange?: (theme: Theme) => void;
} & UseThemeOptions;

/** Light, Dark and System side by side, for a settings page. */
export function ThemeSelect({
  value,
  onValueChange,
  storageKey,
  transition,
  size = "sm",
  ...props
}: ThemeSelectProps) {
  const controlled = value !== undefined;
  const page = useDocumentTheme({ storageKey, transition }, !controlled);
  // Empty until hydration: no option is checked, and the pill appears in place.
  const current = value ?? page.theme ?? "";
  return (
    <SegmentedControl
      aria-label="Theme"
      size={size}
      {...props}
      value={current}
      onValueChange={(next) => {
        onValueChange?.(next as Theme);
        if (!controlled) page.setTheme(next as Theme);
      }}
    >
      <Segment value="light">Light</Segment>
      <Segment value="dark">Dark</Segment>
      <Segment value="system">System</Segment>
    </SegmentedControl>
  );
}
